parts.text:
{
  "conversations": [
    {
      "title": "Ask for a specific place",
      "lines": [
        { "speaker": "you", "text": "Where's the train station?" },
        { "speaker": "partner", "text": "It's near the main square." },
        { "speaker": "partner", "text": "It's far from here.", "or": true },
        { "speaker": "you", "text": "Can I take the bus there?" },
        { "speaker": "partner", "text": "Yes, take bus twenty-two." },
        { "speaker": "you", "text": "Thanks a lot." }
      ],
      "vocab": ["station", "square", "bus", "near", "far", "take"]
    },
    {
      "title": "Understand basic directions",
      "lines": [
        { "speaker": "partner", "text": "Go straight ahead." },
        { "speaker": "partner", "text": "Turn left at the corner.", "or": true },
        { "speaker": "you", "text": "Is it on the right?" },
        { "speaker": "partner", "text": "Yes, right beside the shop." },
        { "speaker": "you", "text": "Thank you." }
      ],
      "vocab": ["straight", "left", "right", "corner", "shop"]
    },
    {
      "title": "Ask to repeat or slow down",
      "lines": [
        { "speaker": "you", "text": "Could you speak slower, please?" },
        { "speaker": "partner", "text": "Sure, go straight and turn right." },
        { "speaker": "you", "text": "Could you repeat that?" },
        { "speaker": "partner", "text": "Turn right at the traffic lights." },
        { "speaker": "you", "text": "Got it, thanks." }
      ],
      "vocab": ["slow", "repeat", "light", "street"]
    }
  ]
}
